static struct task_struct *libperfmgr_tsk;
bool task_is_libperfmgr(struct task_struct *p)
{
	struct task_struct *tsk;
	bool ret;

	rcu_read_lock();
	tsk = READ_ONCE(libperfmgr_tsk);
	ret = tsk && same_thread_group(p, tsk);
	rcu_read_unlock();

	return ret;
